// ===== NODE 5: Phân tích Bottleneck từ dữ liệu thô =====
const data = $input.first().json;
const tasks = data.tasks || [];
const members = data.members || [];
const stuckTasks = data.stuck_tasks || [];
const overdueTasks = data.overdue_tasks || [];
const projects = data.projects || [];
const recentDiagnostics = data.recent_diagnostics || [];

// === 1. STUCK TASKS ANALYSIS ===
const stuckAnalysis = stuckTasks.map(t => {
  const inactiveHours = parseFloat(t.inactive_hours) || 0;
  let severity = 'MEDIUM';
  if (inactiveHours >= 72 || t.priority === 'URGENT') severity = 'CRITICAL';
  else if (inactiveHours >= 48 || t.priority === 'HIGH') severity = 'HIGH';

  const isOverdue = t.due_date ? new Date(t.due_date) < new Date() : false;
  if (isOverdue) severity = 'CRITICAL';

  return {
    task_id: t.task_id,
    title: t.title,
    status: t.status,
    priority: t.priority,
    assignee_name: t.assignee_name || 'Chưa gán',
    assignee_id: t.assignee_id,
    project_name: t.project_name,
    project_id: t.project_id,
    inactive_hours: inactiveHours,
    due_date: t.due_date,
    is_overdue: isOverdue,
    severity: severity
  };
});

// === 2. OVERDUE TASKS ANALYSIS ===
const overdueAnalysis = overdueTasks.map(t => {
  const overdueDays = parseFloat(t.overdue_days) || 0;
  let severity = 'MEDIUM';
  if (overdueDays >= 7 || t.priority === 'URGENT') severity = 'CRITICAL';
  else if (overdueDays >= 3 || t.priority === 'HIGH') severity = 'HIGH';
  else if (overdueDays >= 1) severity = 'MEDIUM';
  else severity = 'LOW';

  return {
    task_id: t.task_id,
    title: t.title,
    status: t.status,
    priority: t.priority,
    assignee_name: t.assignee_name || 'Chưa gán',
    assignee_id: t.assignee_id,
    project_name: t.project_name,
    project_id: t.project_id,
    overdue_days: overdueDays,
    due_date: t.due_date,
    severity: severity
  };
});

// === 3. MEMBER WORKLOAD ANALYSIS ===
const workloadAnalysis = members.map(m => {
  const activeCount = parseInt(m.active_task_count) || 0;
  const maxWorkload = parseInt(m.max_workload) || 5;
  const utilizationRate = maxWorkload > 0 ? Math.round((activeCount / maxWorkload) * 100) : 0;
  const overdueCount = parseInt(m.overdue_task_count) || 0;
  const activePoints = parseInt(m.active_story_points) || 0;

  let isOverloaded = false;
  let severity = 'LOW';
  if (activeCount > maxWorkload) {
    isOverloaded = true;
    severity = activeCount >= maxWorkload * 1.5 ? 'CRITICAL' : 'HIGH';
  } else if (utilizationRate >= 80) {
    severity = 'MEDIUM';
  }

  return {
    member_id: m.member_id,
    full_name: m.full_name,
    email: m.email,
    skills: m.skills,
    max_workload: maxWorkload,
    active_task_count: activeCount,
    completed_task_count: parseInt(m.completed_task_count) || 0,
    overdue_task_count: overdueCount,
    active_story_points: activePoints,
    utilization_rate: utilizationRate,
    is_overloaded: isOverloaded,
    productivity_score: parseFloat(m.productivity_score) || 100,
    severity: severity
  };
});

// === 4. WORKLOAD IMBALANCE ANALYSIS ===
const taskCounts = workloadAnalysis.map(m => m.active_task_count);
const avgTasks = taskCounts.length > 0 ? taskCounts.reduce((a, b) => a + b, 0) / taskCounts.length : 0;
const maxTasks = Math.max(...taskCounts, 0);
const minTasks = Math.min(...taskCounts, 0);
const imbalanceRatio = avgTasks > 0 ? Math.round(((maxTasks - minTasks) / avgTasks) * 100) : 0;

let imbalanceSeverity = 'LOW';
if (imbalanceRatio >= 150) imbalanceSeverity = 'CRITICAL';
else if (imbalanceRatio >= 100) imbalanceSeverity = 'HIGH';
else if (imbalanceRatio >= 50) imbalanceSeverity = 'MEDIUM';

// === 5. PROJECT HEALTH SUMMARY ===
const projectHealth = projects.map(p => {
  const totalTasks = parseInt(p.total_tasks) || 0;
  const doneTasks = parseInt(p.done_tasks) || 0;
  const bottleneckTasks = parseInt(p.bottleneck_tasks) || 0;
  const overduePTasks = parseInt(p.overdue_tasks) || 0;
  const completionRate = totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0;
  const bottleneckRate = totalTasks > 0 ? Math.round((bottleneckTasks / totalTasks) * 100) : 0;

  return {
    project_id: p.project_id,
    project_name: p.name,
    status: p.status,
    deadline: p.deadline,
    total_tasks: totalTasks,
    done_tasks: doneTasks,
    in_progress_tasks: parseInt(p.in_progress_tasks) || 0,
    todo_tasks: parseInt(p.todo_tasks) || 0,
    bottleneck_tasks: bottleneckTasks,
    overdue_tasks: overduePTasks,
    completion_rate: completionRate,
    bottleneck_rate: bottleneckRate
  };
});

// === BUILD ISSUES LIST ===
const issues = [];

// Stuck tasks issues
if (stuckAnalysis.length > 0) {
  const worstSeverity = stuckAnalysis.some(t => t.severity === 'CRITICAL') ? 'CRITICAL' :
                        stuckAnalysis.some(t => t.severity === 'HIGH') ? 'HIGH' : 'MEDIUM';
  issues.push({
    type: 'STUCK_TASKS',
    severity: worstSeverity,
    count: stuckAnalysis.length,
    details: stuckAnalysis
  });
}

// Overdue tasks issues
if (overdueAnalysis.length > 0) {
  const worstSeverity = overdueAnalysis.some(t => t.severity === 'CRITICAL') ? 'CRITICAL' :
                        overdueAnalysis.some(t => t.severity === 'HIGH') ? 'HIGH' : 'MEDIUM';
  issues.push({
    type: 'OVERDUE_DEADLINE',
    severity: worstSeverity,
    count: overdueAnalysis.length,
    details: overdueAnalysis
  });
}

// Member overload issues
const overloadedMembers = workloadAnalysis.filter(m => m.is_overloaded);
if (overloadedMembers.length > 0) {
  const worstSeverity = overloadedMembers.some(m => m.severity === 'CRITICAL') ? 'CRITICAL' : 'HIGH';
  issues.push({
    type: 'MEMBER_OVERLOAD',
    severity: worstSeverity,
    count: overloadedMembers.length,
    details: overloadedMembers
  });
}

// Workload imbalance issue
if (imbalanceRatio >= 50 && members.length >= 2) {
  issues.push({
    type: 'WORKLOAD_IMBALANCE',
    severity: imbalanceSeverity,
    count: 1,
    details: {
      avg_tasks: Math.round(avgTasks * 10) / 10,
      max_tasks: maxTasks,
      min_tasks: minTasks,
      imbalance_ratio: imbalanceRatio,
      member_workloads: workloadAnalysis
    }
  });
}

// Filter out already diagnosed issues (from recent diagnostics)
const recentTypes = recentDiagnostics.map(d => d.diagnostic_type);
const newIssues = issues.filter(i => {
  // Cho phép diagnose lại nếu severity tăng
  const recentSame = recentDiagnostics.find(d => d.diagnostic_type === i.type);
  if (!recentSame) return true;
  const severityOrder = { 'LOW': 0, 'MEDIUM': 1, 'HIGH': 2, 'CRITICAL': 3 };
  return severityOrder[i.severity] > severityOrder[recentSame.severity];
});

return [{
  json: {
    has_issues: newIssues.length > 0,
    total_issues: newIssues.length,
    issues: newIssues,
    all_analysis: {
      stuck_tasks: stuckAnalysis,
      overdue_tasks: overdueAnalysis,
      workload: workloadAnalysis,
      project_health: projectHealth,
      imbalance: {
        ratio: imbalanceRatio,
        severity: imbalanceSeverity,
        avg_tasks: Math.round(avgTasks * 10) / 10,
        max_tasks: maxTasks,
        min_tasks: minTasks
      }
    },
    raw_summary: data.summary,
    analyzed_at: new Date().toISOString()
  }
}];

// ===== NODE 7: Chuẩn bị prompt cho AI =====
const data = $input.first().json;
const issues = data.issues;
const analysis = data.all_analysis;

// Build context string cho AI
let context = '=== DỮ LIỆU PHÂN TÍCH BOTTLENECK CỦA DỰ ÁN ===\n\n';

// 1. Stuck Tasks
if (analysis.stuck_tasks.length > 0) {
  context += '--- TASK BỊ STUCK (Không cập nhật > 24 giờ) ---\n';
  analysis.stuck_tasks.forEach((t, i) => {
    context += `${i+1}. "${t.title}" - Status: ${t.status}, Priority: ${t.priority}, `;
    context += `Assignee: ${t.assignee_name}, Inactive: ${t.inactive_hours} giờ`;
    if (t.is_overdue) context += ' [ĐÃ QUÁ HẠN!]';
    context += `\n`;
  });
  context += '\n';
}

// 2. Overdue Tasks
if (analysis.overdue_tasks.length > 0) {
  context += '--- TASK QUÁ HẠN ---\n';
  analysis.overdue_tasks.forEach((t, i) => {
    context += `${i+1}. "${t.title}" - Status: ${t.status}, Priority: ${t.priority}, `;
    context += `Assignee: ${t.assignee_name}, Quá hạn: ${t.overdue_days} ngày\n`;
  });
  context += '\n';
}

// 3. Member Workload
context += '--- WORKLOAD CỦA CÁC THÀNH VIÊN ---\n';
analysis.workload.forEach((m, i) => {
  context += `${i+1}. ${m.full_name}: ${m.active_task_count}/${m.max_workload} tasks `;
  context += `(${m.utilization_rate}% utilization), ${m.overdue_task_count} overdue, `;
  context += `${m.active_story_points} story points`;
  if (m.is_overloaded) context += ' [QUÁ TẢI!]';
  context += `\n`;
});
context += '\n';

// 4. Workload Imbalance
context += `--- CÂN BẰNG WORKLOAD ---\n`;
context += `Trung bình: ${analysis.imbalance.avg_tasks} tasks/member, `;
context += `Cao nhất: ${analysis.imbalance.max_tasks}, Thấp nhất: ${analysis.imbalance.min_tasks}, `;
context += `Tỷ lệ mất cân bằng: ${analysis.imbalance.ratio}%\n\n`;

// 5. Project Health
context += '--- SỨC KHỎE DỰ ÁN ---\n';
analysis.project_health.forEach((p, i) => {
  context += `${i+1}. "${p.project_name}" - Completion: ${p.completion_rate}%, `;
  context += `Bottleneck: ${p.bottleneck_tasks}/${p.total_tasks} tasks, `;
  context += `Overdue: ${p.overdue_tasks} tasks, Deadline: ${p.deadline}\n`;
});

// Build issues summary
let issuesSummary = '\n=== CÁC VẤN ĐỀ PHÁT HIỆN ===\n';
issues.forEach((issue, i) => {
  issuesSummary += `${i+1}. [${issue.severity}] ${issue.type}: ${issue.count} items\n`;
});

const prompt = `Bạn là AI Bottleneck Diagnostic Expert cho hệ thống quản lý dự án.

Dựa trên dữ liệu thực tế sau, hãy phân tích chi tiết các bottleneck và đưa ra giải pháp.

${context}
${issuesSummary}

Hãy trả về KẾT QUẢ PHÂN TÍCH dưới dạng JSON array, mỗi phần tử là một diagnostic report theo format SAU (KHÔNG thêm markdown, KHÔNG thêm text ngoài JSON):

[
  {
    "diagnostic_type": "STUCK_TASKS | OVERDUE_DEADLINE | MEMBER_OVERLOAD | WORKLOAD_IMBALANCE",
    "severity": "LOW | MEDIUM | HIGH | CRITICAL",
    "title": "Tiêu đề ngắn gọn mô tả vấn đề (tiếng Việt)",
    "description": "Phân tích chi tiết nguyên nhân gốc rễ (root cause) của vấn đề (tiếng Việt)",
    "evidence": [
      { "type": "metric", "detail": "Mô tả bằng chứng cụ thể" }
    ],
    "recommendations": [
      { "action": "Hành động cụ thể cần thực hiện", "priority": "HIGH", "detail": "Chi tiết cách thực hiện" }
    ],
    "affected_tasks": [
      { "task_id": "uuid-of-task", "title": "Tên task" }
    ],
    "affected_members": [
      { "member_id": "uuid-of-member", "name": "Tên member" }
    ]
  }
]

Lưu ý:
- Chỉ tạo diagnostic cho các vấn đề thực sự nghiêm trọng, không tạo nếu mọi thứ bình thường.
- Mỗi diagnostic phải có ít nhất 1 evidence và 1 recommendation.
- severity phải phản ánh đúng mức độ nghiêm trọng dựa trên dữ liệu.
- affected_tasks và affected_members phải chứa ID thực từ dữ liệu được cung cấp.
- Trả về JSON array THUẦN TÚY, không có markdown code block, không có text giải thích.`;

return [{
  json: {
    prompt: prompt,
    issues: issues,
    analysis: analysis,
    raw_summary: data.raw_summary
  }
}];

// ===== NODE 9: Parse và validate AI response =====
const input = $input.first().json;
const issues = $('Code - Build AI Prompt').first().json.issues;
const analysis = $('Code - Build AI Prompt').first().json.analysis;

try {
  // Lấy content từ AI response
  let aiContent = '';
  if (input.choices && input.choices.length > 0) {
    aiContent = input.choices[0].message?.content || '';
  } else if (input.message?.content) {
    aiContent = input.message.content;
  } else if (typeof input === 'string') {
    aiContent = input;
  }

  if (!aiContent || aiContent.trim().length === 0) {
    throw new Error('AI trả về response rỗng');
  }

  // Clean markdown code blocks nếu có
  let cleanContent = aiContent.trim();
  if (cleanContent.startsWith('```json')) {
    cleanContent = cleanContent.replace(/^```json\s*/, '').replace(/```\s*$/, '');
  } else if (cleanContent.startsWith('```')) {
    cleanContent = cleanContent.replace(/^```\s*/, '').replace(/```\s*$/, '');
  }
  cleanContent = cleanContent.trim();

  // Parse JSON
  let diagnostics = JSON.parse(cleanContent);

  // Ensure it's an array
  if (!Array.isArray(diagnostics)) {
    if (diagnostics.diagnostics && Array.isArray(diagnostics.diagnostics)) {
      diagnostics = diagnostics.diagnostics;
    } else {
      diagnostics = [diagnostics];
    }
  }

  // Validate each diagnostic
  const validTypes = ['STUCK_TASKS', 'OVERDUE_DEADLINE', 'MEMBER_OVERLOAD', 'WORKLOAD_IMBALANCE', 'GENERAL'];
  const validSeverities = ['LOW', 'MEDIUM', 'HIGH', 'CRITICAL'];

  const validDiagnostics = diagnostics
    .filter(d => d && typeof d === 'object')
    .map(d => {
      // Normalize type
      let diagType = (d.diagnostic_type || 'GENERAL').toUpperCase();
      if (!validTypes.includes(diagType)) diagType = 'GENERAL';

      // Normalize severity
      let severity = (d.severity || 'MEDIUM').toUpperCase();
      if (!validSeverities.includes(severity)) severity = 'MEDIUM';

      return {
        diagnostic_type: diagType,
        severity: severity,
        title: d.title || 'Bottleneck detected',
        description: d.description || 'No description provided',
        evidence: Array.isArray(d.evidence) ? d.evidence : [],
        recommendations: Array.isArray(d.recommendations) ? d.recommendations : [],
        affected_tasks: Array.isArray(d.affected_tasks) ? d.affected_tasks : [],
        affected_members: Array.isArray(d.affected_members) ? d.affected_members : []
      };
    })
    .filter(d => d.title && d.description);

  if (validDiagnostics.length === 0) {
    throw new Error('Không có diagnostic hợp lệ sau khi validate');
  }

  return [{
    json: {
      parse_success: true,
      diagnostics: validDiagnostics,
      diagnostics_count: validDiagnostics.length,
      ai_raw_response: aiContent
    }
  }];

} catch (error) {
  // Fallback: tạo diagnostic từ dữ liệu phân tích (không cần AI)
  const fallbackDiagnostics = [];

  issues.forEach(issue => {
    const diag = {
      diagnostic_type: issue.type,
      severity: issue.severity,
      title: '',
      description: '',
      evidence: [],
      recommendations: [],
      affected_tasks: [],
      affected_members: []
    };

    switch (issue.type) {
      case 'STUCK_TASKS':
        diag.title = `${issue.count} task(s) bị stuck cần xử lý`;
        diag.description = `Phát hiện ${issue.count} task không có hoạt động trong hơn 24 giờ.`;
        diag.evidence = issue.details.map(t => ({
          type: 'stuck_task',
          detail: `Task "${t.title}" - inactive ${t.inactive_hours} giờ (${t.status})`
        }));
        diag.recommendations = [{ action: 'Review và reassign các task bị stuck', priority: 'HIGH', detail: 'Liên hệ assignee để xác nhận tình trạng' }];
        diag.affected_tasks = issue.details.map(t => ({ task_id: t.task_id, title: t.title }));
        diag.affected_members = [...new Map(issue.details.filter(t => t.assignee_id).map(t => [t.assignee_id, { member_id: t.assignee_id, name: t.assignee_name }])).values()];
        break;
      case 'OVERDUE_DEADLINE':
        diag.title = `${issue.count} task(s) đã quá hạn deadline`;
        diag.description = `Phát hiện ${issue.count} task đã vượt quá deadline mà chưa hoàn thành.`;
        diag.evidence = issue.details.map(t => ({
          type: 'overdue',
          detail: `Task "${t.title}" - quá hạn ${t.overdue_days} ngày (${t.status})`
        }));
        diag.recommendations = [{ action: 'Ưu tiên hoàn thành các task quá hạn', priority: 'CRITICAL', detail: 'Xem xét reassign hoặc giảm scope' }];
        diag.affected_tasks = issue.details.map(t => ({ task_id: t.task_id, title: t.title }));
        diag.affected_members = [...new Map(issue.details.filter(t => t.assignee_id).map(t => [t.assignee_id, { member_id: t.assignee_id, name: t.assignee_name }])).values()];
        break;
      case 'MEMBER_OVERLOAD':
        diag.title = `${issue.count} thành viên bị quá tải`;
        diag.description = `Phát hiện ${issue.count} thành viên có số task vượt quá giới hạn workload.`;
        diag.evidence = issue.details.map(m => ({
          type: 'overload',
          detail: `${m.full_name}: ${m.active_task_count}/${m.max_workload} tasks (${m.utilization_rate}%)`
        }));
        diag.recommendations = [{ action: 'Phân bổ lại task cho các thành viên ít việc hơn', priority: 'HIGH', detail: 'Dùng Workload Balancer để cân bằng' }];
        diag.affected_members = issue.details.map(m => ({ member_id: m.member_id, name: m.full_name }));
        break;
      case 'WORKLOAD_IMBALANCE':
        diag.title = `Mất cân bằng workload nghiêm trọng (${issue.details.imbalance_ratio}%)`;
        diag.description = `Workload phân bố không đều giữa các thành viên.`;
        diag.evidence = [{
          type: 'imbalance',
          detail: `Trung bình ${issue.details.avg_tasks} tasks, cao nhất ${issue.details.max_tasks}, thấp nhất ${issue.details.min_tasks}`
        }];
        diag.recommendations = [{ action: 'Cân bằng lại workload giữa các thành viên', priority: 'MEDIUM', detail: 'Chuyển task từ người nhiều sang người ít' }];
        diag.affected_members = (issue.details.member_workloads || []).map(m => ({ member_id: m.member_id, name: m.full_name }));
        break;
    }

    fallbackDiagnostics.push(diag);
  });

  return [{
    json: {
      parse_success: false,
      parse_error: error.message,
      diagnostics: fallbackDiagnostics,
      diagnostics_count: fallbackDiagnostics.length,
      ai_raw_response: 'FALLBACK - AI parse failed: ' + error.message
    }
  }];
}

// ===== NODE 11: Split diagnostics thành individual items =====
// Mỗi diagnostic cần được gửi riêng lẻ đến API
const data = $input.first().json;
const diagnostics = data.diagnostics;
const aiRawResponse = data.ai_raw_response;
const analysis = $('Code - Analyze Bottlenecks').first().json.all_analysis;

// Lấy project_id đầu tiên từ analysis (hoặc từ affected tasks)
const defaultProjectId = analysis.project_health.length > 0 ? analysis.project_health[0].project_id : null;

const items = diagnostics.map(d => {
  // Tìm project_id từ affected_tasks hoặc dùng default
  let projectId = defaultProjectId;
  if (d.affected_tasks && d.affected_tasks.length > 0) {
    const taskProjectId = analysis.stuck_tasks
      .concat(analysis.overdue_tasks)
      .find(t => t.task_id === d.affected_tasks[0].task_id)?.project_id;
    if (taskProjectId) projectId = taskProjectId;
  }

  return {
    json: {
      project_id: projectId,
      diagnostic_type: d.diagnostic_type,
      severity: d.severity,
      title: d.title,
      description: d.description,
      evidence: d.evidence,
      recommendations: d.recommendations,
      affected_tasks: d.affected_tasks,
      affected_members: d.affected_members,
      ai_raw_response: aiRawResponse,
      metadata: {
        source: 'n8n_flow7',
        parse_success: data.parse_success,
        analyzed_at: new Date().toISOString()
      }
    }
  };
});

return items;

// ===== NODE 18: Tổng hợp kết quả cuối cùng =====
const savedResults = $input.all();
const analysisData = $('Code - Analyze Bottlenecks').first().json;
const parseData = $('Code - Parse AI Response').first().json;

const successCount = savedResults.filter(r => r.json.id || r.json.severity).length;
const errorCount = savedResults.filter(r => r.json.error).length;

// Đếm theo severity
const severityCounts = { CRITICAL: 0, HIGH: 0, MEDIUM: 0, LOW: 0 };
savedResults.forEach(r => {
  const sev = r.json.severity;
  if (sev && severityCounts.hasOwnProperty(sev)) {
    severityCounts[sev]++;
  }
});

return [{
  json: {
    success: true,
    flow: 'flow7-ai-bottleneck-diagnostic',
    summary: {
      total_issues_detected: analysisData.total_issues,
      diagnostics_created: successCount,
      save_errors: errorCount,
      ai_parse_success: parseData.parse_success,
      severity_breakdown: severityCounts,
      data_summary: analysisData.raw_summary
    },
    diagnostics: savedResults.map(r => r.json),
    processed_at: new Date().toISOString()
  }
}];

// ===== No Issues Detected =====
return [{
  json: {
    success: true,
    flow: 'flow7-ai-bottleneck-diagnostic',
    message: 'Không phát hiện bottleneck mới. Tất cả đang hoạt động bình thường!',
    total_issues: 0,
    scanned_at: new Date().toISOString()
  }
}];

// ===== No Data Available =====
return [{
  json: {
    success: true,
    flow: 'flow7-ai-bottleneck-diagnostic',
    message: 'Không có dữ liệu task nào để phân tích. Database có thể trống.',
    total_tasks: 0,
    scanned_at: new Date().toISOString()
  }
}];

// ===== AI Response Invalid - Log Error =====
return [{
  json: {
    success: false,
    flow: 'flow7-ai-bottleneck-diagnostic',
    message: 'AI không trả về kết quả hợp lệ nhưng đã sử dụng fallback logic.',
    scanned_at: new Date().toISOString()
  }
}];

// ===== Global Error Handler =====
const errorData = $input.first().json;

const errorMessage = errorData.execution?.error?.message || 
                     errorData.error?.message || 
                     'Unknown error in Flow 7';
const errorNode = errorData.execution?.lastNodeExecuted || 'unknown';

console.error(`[Flow 7 Error] Node: ${errorNode}, Error: ${errorMessage}`);

return [{
